import type { WorkflowAuditResponse } from "../src/types/atlasAgent";
import nativeAuditFixture from "./fixtures/commit-outcome-unknown.json" with { type: "json" };
import { expect, test } from "./mission-control-fixtures";

// Synthetic, generated by the native Agent audit projection. This page can
// inspect an uncertain outcome but has no authority to repeat a local commit.
const stageNames = ["candidate", "planning", "plan", "workflow", "implementation", "approvals", "execution", "verification", "review", "commit"] as const;
const repositoryAudit = {
    ...nativeAuditFixture,
    effect_kind: "repository_change" as const,
    timeline: nativeAuditFixture.timeline.map((stage) => {
        const name = stageNames.find((candidate) => candidate === stage.name);
        if (!name) throw new Error("Unknown native audit fixture stage");
        return { ...stage, name };
    }),
};
const audit: WorkflowAuditResponse = repositoryAudit;

for (const viewport of [{ width: 390, height: 844 }, { width: 1280, height: 900 }]) {
    test.describe(`Uncertain local commit at ${viewport.width}px`, () => {
        test.use({ viewport });

        test("explains uncertainty and keeps reload read-only", async ({ page, baseURL, rejectedMutationRequests }) => {
            expect(nativeAuditFixture.effect_kind).toBe("repository_change");
            const expectedOrigin = new URL(baseURL ?? "http://127.0.0.1:5173").origin;
            let auditReads = 0;
            await page.route(`**/agent-api/api/v1/agent/workflows/${audit.workflow_id}/audit`, async (route) => {
                const request = route.request();
                if (request.method() !== "GET" || new URL(request.url()).origin !== expectedOrigin) {
                    await route.fulfill({ status: 405, json: { detail: "Fixture permits exact-origin reads only." } });
                    return;
                }
                auditReads += 1;
                await route.fulfill({ json: audit });
            });

            await page.goto(`/workflows/${audit.workflow_id}/audit`);
            const commitSection = page.locator("section").filter({
                has: page.getByRole("heading", { name: /^Commit Result$/i }),
            });
            await expect(commitSection.getByText("Status: Outcome unknown", { exact: true })).toBeVisible();
            await expect(page.getByText(
                "Git may have created a local commit. Inspect the repository before recovery; do not repeat the commit.",
                { exact: true },
            )).toBeVisible();
            await expect(page.getByRole("button", { name: /retry|resume|commit|approve|execute/i })).toHaveCount(0);

            const readsBeforeReload = auditReads;
            await page.reload();
            await expect(commitSection.getByText("Status: Outcome unknown", { exact: true })).toBeVisible();
            await expect.poll(() => auditReads).toBeGreaterThan(readsBeforeReload);
            expect(rejectedMutationRequests).toEqual([]);
        });
    });
}
